import {escape as esc,normalize} from './utils.js';
// Paginated checkboxes avoid nested scroll regions and retain selections across pages.
export function mountPicker(container,{id,rows,selected,label,detail=()=>'',pageSize=6,onChange=()=>{}}){
  let query='',page=1;
  container.innerHTML=`<label class="field">Buscar ${esc(label)}<input id="${id}-search" type="search" placeholder="Digite para filtrar..." data-testid="${id}-search"></label><div id="${id}-actions" class="picker-actions"></div><div id="${id}-list"></div><div id="${id}-pages" class="picker-pages"></div>`;
  function render(){const matches=rows.filter(r=>normalize(labelValue(r)+' '+detail(r)).includes(normalize(query)));const pages=Math.max(1,Math.ceil(matches.length/pageSize));const actions=container.querySelector('#'+id+'-actions');actions.innerHTML=`<button type="button" class="subtle-link" data-select-matches>Selecionar resultados (${matches.length})</button><button type="button" class="subtle-link" data-clear-selection>Limpar seleção</button>`;actions.querySelector('[data-select-matches]').onclick=()=>{matches.forEach(r=>selected.add(r.id));render();onChange()};actions.querySelector('[data-clear-selection]').onclick=()=>{selected.clear();render();onChange()};page=Math.min(page,pages);container.querySelector('#'+id+'-list').innerHTML=`<div class="picker-count">${selected.size} selecionado(s) · ${matches.length} disponível(is)</div>`+matches.slice((page-1)*pageSize,page*pageSize).map(row=>`<label class="picker-option"><input type="checkbox" value="${esc(row.id)}" ${selected.has(row.id)?'checked':''} data-testid="${id}-option"><span><strong>${esc(labelValue(row))}</strong><small>${esc(detail(row))}</small></span></label>`).join('')+(matches.length?'':'<p class="picker-count">Nenhum cadastro encontrado.</p>');container.querySelectorAll('input[type="checkbox"]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.value):selected.delete(el.value);render();onChange()});const pager=container.querySelector('#'+id+'-pages');pager.innerHTML=`<button type="button" class="btn" data-prev ${page===1?'disabled':''}>‹ Anterior</button><span>${page} de ${pages}</span><button type="button" class="btn" data-next ${page===pages?'disabled':''}>Próxima ›</button>`;pager.querySelector('[data-prev]').onclick=()=>{page--;render()};pager.querySelector('[data-next]').onclick=()=>{page++;render()}}
  function labelValue(row){return row.product||row.name||row.number||''}
  container.querySelector('input[type="search"]').oninput=e=>{query=e.target.value;page=1;render()};render();
}
